type Granularity = 'day' | 'week' | 'month';
type ProviderFilter = 'all' | 'codex' | 'claude';
type AuthorFilter = 'mine' | 'all';

// The URL filter codec (TECH › State ownership: filters are URL state). The six filter keys are the same ones every
// analytics route accepts (docs/tech/local-api.md › Filters): start, end, gran, repos, provider, author.
//
//   - Defaults are omitted from the URL, so no params means This week, All repos, All providers, Mine.
//   - There is no `period` key: the period is whatever preset the start and end happen to match, else Custom.
//   - Whatever the URL says, `decodeFilters` answers a range the API accepts (checkRange in shared/domain/periods.ts):
//     clamped to the 12-month lookback, and no later than the end of the current week or month.
//
// The codec is pure and takes `today` and `lookbackStart` from /api/bootstrap, because the report timezone is the
// server's. It does its own calendar-date arithmetic on `YYYY-MM-DD` strings with UTC dates, which is exact for dates
// that carry no time of day, and means the browser needs no `Temporal` (shipped in Chromium and Firefox, not
// everywhere). test/e2e/filters.spec.ts checks every helper here against shared/domain/periods.ts.

/** The query keys this codec owns. Anything else in the URL (Delivery's `q`, Trends' `sel`) is left alone. */
export const FILTER_KEYS = ['start', 'end', 'gran', 'repos', 'provider', 'author'] as const;

/** Params that point into the current range, so they are dropped when the range or grouping changes. */
const RANGE_BOUND_KEYS = ['sel'] as const;

const GRANULARITIES: readonly Granularity[] = ['day', 'week', 'month'];
const PROVIDERS: readonly ProviderFilter[] = ['all', 'codex', 'claude'];
const AUTHORS: readonly AuthorFilter[] = ['mine', 'all'];

export interface FilterContext {
  /** The calendar date today in the report timezone. */
  today: string;
  /** `today − 365 days`: the earliest date a report may start on. */
  lookbackStart: string;
}

export interface Filters {
  start: string;
  end: string;
  gran: Granularity;
  /** Canonical repo ids, sorted and without duplicates. Empty means all repos. */
  repos: string[];
  provider: ProviderFilter;
  author: AuthorFilter;
}

export type PeriodPreset =
  'today' | 'this-week' | 'this-month' | 'last-30' | 'last-90' | 'last-12m';
export type Period = PeriodPreset | 'custom';

// ---- calendar dates ----------------------------------------------------------------------------------------------

const DATE_SHAPE = /^(\d{4})-(\d{2})-(\d{2})$/;
const DAY_MS = 86_400_000;

function parts(date: string): [number, number, number] {
  const match = DATE_SHAPE.exec(date);
  if (!match) throw new RangeError(`Not a YYYY-MM-DD date: ${date}`);
  return [Number(match[1]), Number(match[2]), Number(match[3])];
}

const utc = (date: string): number => {
  const [y, m, d] = parts(date);
  return Date.UTC(y, m - 1, d);
};
const fromUtc = (ms: number): string => new Date(ms).toISOString().slice(0, 10);

/** True for a real calendar date written `YYYY-MM-DD` (2026-02-30 is not one). */
export function isIsoDate(value: string): boolean {
  const match = DATE_SHAPE.exec(value);
  if (!match) return false;
  const [y, m, d] = [Number(match[1]), Number(match[2]), Number(match[3])];
  const probe = new Date(Date.UTC(y, m - 1, d));
  return probe.getUTCFullYear() === y && probe.getUTCMonth() === m - 1 && probe.getUTCDate() === d;
}

export const addDays = (date: string, days: number): string => fromUtc(utc(date) + days * DAY_MS);
/** Whole calendar days from `a` to `b` (negative when `b` is earlier). */
export const diffDays = (a: string, b: string): number => Math.round((utc(b) - utc(a)) / DAY_MS);
/** 1 = Monday … 7 = Sunday. */
const isoWeekday = (date: string): number => ((new Date(utc(date)).getUTCDay() + 6) % 7) + 1;
export const weekStart = (date: string): string => addDays(date, 1 - isoWeekday(date));
export const weekEnd = (date: string): string => addDays(weekStart(date), 6);
export const monthStart = (date: string): string => `${date.slice(0, 8)}01`;
export const monthEnd = (date: string): string => {
  const [y, m] = parts(date);
  return fromUtc(Date.UTC(y, m, 0));
};

/** `day` for ≤ 45 days, `week` for ≤ 200, else `month` (local-api › Filters). */
export function defaultGranularity(start: string, end: string): Granularity {
  const days = diffDays(start, end) + 1;
  return days <= 45 ? 'day' : days <= 200 ? 'week' : 'month';
}

const clampDate = (date: string, low: string, high: string): string =>
  date < low ? low : date > high ? high : date;

/**
 * The latest date a range may end on, which is what the API accepts (`checkRange` in shared/domain/periods.ts): an end past today
 * is allowed up to the end of the current week or month, whichever is later (the This week and This month presets).
 */
export const latestEnd = (ctx: FilterContext): string =>
  weekEnd(ctx.today) > monthEnd(ctx.today) ? weekEnd(ctx.today) : monthEnd(ctx.today);

/**
 * `range` moved inside what the API accepts, and nothing else: each date goes to the lookback start or to `latestEnd` only when
 * it is outside them. A week that runs to Sunday, or a day later this week, keeps its own dates.
 */
export function clampRange(
  range: { start: string; end: string },
  ctx: FilterContext,
): { start: string; end: string } {
  const high = latestEnd(ctx);
  return {
    start: clampDate(range.start, ctx.lookbackStart, high),
    end: clampDate(range.end, ctx.lookbackStart, high),
  };
}

// ---- periods -----------------------------------------------------------------------------------------------------

/** The date range of a period preset. This week and This month may end after today. */
export function presetRange(
  preset: PeriodPreset,
  ctx: FilterContext,
): { start: string; end: string } {
  const { today } = ctx;
  switch (preset) {
    case 'today':
      return { start: today, end: today };
    case 'this-week':
      return { start: weekStart(today), end: weekEnd(today) };
    case 'this-month':
      return { start: monthStart(today), end: monthEnd(today) };
    case 'last-30':
      return { start: addDays(today, -29), end: today };
    case 'last-90':
      return { start: addDays(today, -89), end: today };
    case 'last-12m':
      return { start: ctx.lookbackStart, end: today };
  }
}

const PRESETS: readonly PeriodPreset[] = [
  'today',
  'this-week',
  'this-month',
  'last-30',
  'last-90',
  'last-12m',
];

/** The preset whose range is exactly `start..end`, else `custom`. */
export function periodOf(range: { start: string; end: string }, ctx: FilterContext): Period {
  return (
    PRESETS.find((preset) => {
      const r = presetRange(preset, ctx);
      return r.start === range.start && r.end === range.end;
    }) ?? 'custom'
  );
}

/** What a hand-typed custom range is checked against: both dates, in order, inside `lookbackStart..today`. */
export type CustomRangeCheck =
  { ok: true } | { ok: false; reason: 'missing' | 'order' | 'outside' };

export function checkCustomRange(start: string, end: string, ctx: FilterContext): CustomRangeCheck {
  if (!isIsoDate(start) || !isIsoDate(end)) return { ok: false, reason: 'missing' };
  if (start > end) return { ok: false, reason: 'order' };
  if (start < ctx.lookbackStart || end > ctx.today) return { ok: false, reason: 'outside' };
  return { ok: true };
}

// ---- decode and encode -------------------------------------------------------------------------------------------

const normalizeRepos = (ids: readonly string[]): string[] =>
  [...new Set(ids.map((id) => id.trim()).filter(Boolean))].sort();

/** The filters a URL means. Never throws and never returns a range the API would refuse. */
export function decodeFilters(params: URLSearchParams, ctx: FilterContext): Filters {
  const week = presetRange('this-week', ctx);
  const rawStart = params.get('start');
  const rawEnd = params.get('end');
  let start = rawStart !== null && isIsoDate(rawStart) ? rawStart : week.start;
  let end = rawEnd !== null && isIsoDate(rawEnd) ? rawEnd : week.end;
  if (start > end) [start, end] = [end, start];
  ({ start, end } = clampRange({ start, end }, ctx));

  const gran = params.get('gran');
  const provider = params.get('provider');
  const author = params.get('author');
  return {
    start,
    end,
    gran: GRANULARITIES.find((g) => g === gran) ?? defaultGranularity(start, end),
    repos: normalizeRepos((params.get('repos') ?? '').split(',')),
    provider: PROVIDERS.find((p) => p === provider) ?? 'all',
    author: AUTHORS.find((a) => a === author) ?? 'mine',
  };
}

/** The non-default filters as URL params, in a fixed key order. Empty for the default view. */
export function encodeFilters(filters: Filters, ctx: FilterContext): Record<string, string> {
  const out: Record<string, string> = {};
  const week = presetRange('this-week', ctx);
  if (filters.start !== week.start || filters.end !== week.end) {
    out['start'] = filters.start;
    out['end'] = filters.end;
  }
  if (filters.gran !== defaultGranularity(filters.start, filters.end)) out['gran'] = filters.gran;
  if (filters.repos.length > 0) out['repos'] = filters.repos.join(',');
  if (filters.provider !== 'all') out['provider'] = filters.provider;
  if (filters.author !== 'mine') out['author'] = filters.author;
  return out;
}

export const defaultFilters = (ctx: FilterContext): Filters =>
  decodeFilters(new URLSearchParams(), ctx);

/** What a control can ask for. A new range always takes the default grouping for its length. */
export type FilterChange =
  | { period: PeriodPreset }
  | { range: { start: string; end: string } }
  | { gran: Granularity }
  | { repos: readonly string[] }
  | { provider: ProviderFilter }
  | { author: AuthorFilter }
  | { reset: true };

export function applyChange(current: Filters, change: FilterChange, ctx: FilterContext): Filters {
  if ('reset' in change) return defaultFilters(ctx);
  if ('period' in change) return withRange(current, presetRange(change.period, ctx));
  if ('range' in change) return withRange(current, change.range);
  if ('gran' in change) return { ...current, gran: change.gran };
  if ('repos' in change) return { ...current, repos: normalizeRepos(change.repos) };
  if ('provider' in change) return { ...current, provider: change.provider };
  return { ...current, author: change.author };
}

const withRange = (current: Filters, range: { start: string; end: string }): Filters => ({
  ...current,
  ...range,
  gran: defaultGranularity(range.start, range.end),
});

// ---- the URL -----------------------------------------------------------------------------------------------------

// `/` and `,` are legal in a query string and make `repos=kelvin/a,kelvin/b` readable, so they stay unescaped.
const escapeParam = (text: string): string =>
  encodeURIComponent(text).replace(/%2F/gi, '/').replace(/%2C/gi, ',');

/** `?…` for `filters` plus every non-filter param of `currentSearch`, or an empty string when there is nothing to say. */
export function searchFor(
  currentSearch: string,
  filters: Filters,
  ctx: FilterContext,
  options: { dropRangeBound?: boolean } = {},
): string {
  const owned = new Set<string>([
    ...FILTER_KEYS,
    ...(options.dropRangeBound ? RANGE_BOUND_KEYS : []),
  ]);
  const others = [...new URLSearchParams(currentSearch)].filter(([key]) => !owned.has(key));
  const pairs = [...Object.entries(encodeFilters(filters, ctx)), ...others];
  if (pairs.length === 0) return '';
  return `?${pairs.map(([key, value]) => `${escapeParam(key)}=${escapeParam(value)}`).join('&')}`;
}

/** The search string after `change`: the new filters, other params kept, a selected bucket dropped if the range moved. */
export function searchAfter(
  currentSearch: string,
  change: FilterChange,
  ctx: FilterContext,
): string {
  const before = decodeFilters(new URLSearchParams(currentSearch), ctx);
  const after = applyChange(before, change, ctx);
  const moved =
    before.start !== after.start || before.end !== after.end || before.gran !== after.gran;
  return searchFor(currentSearch, after, ctx, { dropRangeBound: moved });
}

/**
 * The search string the URL should have, or null when it already says exactly what it means: no defaults spelled out,
 * no garbage, no out-of-range dates, no repeated keys.
 */
export function canonicalSearch(currentSearch: string, ctx: FilterContext): string | null {
  const params = new URLSearchParams(currentSearch);
  const wanted = encodeFilters(decodeFilters(params, ctx), ctx);
  const same = FILTER_KEYS.every(
    (key) =>
      params.getAll(key).length === (key in wanted ? 1 : 0) &&
      params.get(key) === (wanted[key] ?? null),
  );
  return same ? null : searchFor(currentSearch, decodeFilters(params, ctx), ctx);
}

/** The shared analytics query parameters for `filters`: pass to `apiGet` as `query`. */
export function filtersQuery(filters: Filters) {
  return {
    start: filters.start,
    end: filters.end,
    gran: filters.gran,
    ...(filters.repos.length > 0 ? { repos: filters.repos.join(',') } : {}),
    provider: filters.provider,
    author: filters.author,
  };
}
